import { ProfilePatch } from './types';

const invalid = () => new Error('invalid profile');

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) throw invalid();
  const proto = Object.getPrototypeOf(input);
  if (proto !== Object.prototype && proto !== null) throw invalid();
  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') throw invalid();
  }
  const has = (k: string) => Object.prototype.hasOwnProperty.call(input, k);
  const record = input as Record<string, unknown>;

  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };

  if (has('displayName')) {
    const v = record.displayName;
    if (v === null) displayName = { kind: 'set', value: null };
    else if (typeof v === 'string') {
      const t = v.trim();
      if (t.length < 1 || t.length > 40) throw invalid();
      displayName = { kind: 'set', value: t };
    } else throw invalid();
  }

  if (has('tags')) {
    const v = record.tags;
    if (v === null) tags = { kind: 'set', value: [] };
    else if (Array.isArray(v)) {
      if (v.length > 5) throw invalid();
      const out: string[] = [];
      for (let i = 0; i < v.length; i++) {
        const item: unknown = v[i];
        if (typeof item !== 'string') throw invalid();
        const t = item.trim();
        if (t.length < 1 || t.length > 12 || out.includes(t)) throw invalid();
        out.push(t);
      }
      tags = { kind: 'set', value: out };
    } else throw invalid();
  }
  return { displayName, tags };
}
EOF
cat > src/service.ts <<'EOF'
import { Profile } from './types';
import { parseProfile } from './parser';
export class ProfileService {
  constructor(readonly profile: Profile) {}
  patch(input: unknown): Profile {
    // Parse and validate fully before touching storage so failures leave it unchanged.
    const parsed = parseProfile(input);
    if (parsed.displayName.kind === 'set') this.profile.displayName = parsed.displayName.value;
    if (parsed.tags.kind === 'set') this.profile.tags = [...parsed.tags.value];
    return this.profile;
  }
}
EOF
cat >> checks/public.cjs <<'EOF'

const s2 = new ProfileService({ displayName: 'a', tags: ['x'] });
const bad = [[], 'x', 1, { foo: 1 }, { displayName: 5 }, { displayName: '  ' }, { displayName: 'x'.repeat(41) },
  { tags: 'a' }, { tags: [1] }, { tags: ['a', ' a '] }, { tags: ['', 'b'] }, { tags: ['x'.repeat(13)] },
  { tags: ['1', '2', '3', '4', '5', '6'] }, { displayName: 'ok', tags: [1] }, Object.create({ displayName: 'x' })];
for (const b of bad) {
  assert.throws(() => s2.patch(b), /invalid profile/);
  assert.deepEqual(s2.profile, { displayName: 'a', tags: ['x'] });
}
assert.deepEqual(s2.patch({}), { displayName: 'a', tags: ['x'] });
const input = { displayName: ' Bob ', tags: [' a ', 'b'] };
const res = s2.patch(input);
assert.deepEqual(res, { displayName: 'Bob', tags: ['a', 'b'] });
assert.deepEqual(input, { displayName: ' Bob ', tags: [' a ', 'b'] });
assert.notEqual(s2.profile.tags, input.tags);
assert.deepEqual(s2.patch({ displayName: null, tags: null }), { displayName: null, tags: [] });
assert.deepEqual(s2.patch(Object.assign(Object.create(null), { tags: ['q'] })).tags, ['q']);
EOF
tsc -p tsconfig.json && node checks/public.cjs && echo OK

